package com.nthexperience.desktop;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
/** Runs against the real preceding APK, then the new APK installed with -r. */
public final class ElevenUpgradeSmoke extends Instrumentation {
 MainActivity home;DesktopStore store;String phase;int checks;
 final String note="A note retained through an Eleven update.";
 @Override public void onCreate(Bundle args){super.onCreate(args);phase=args.getString("phase","verify");start();}
 @Override public void onStart(){Bundle out=new Bundle();try{
  store=new DesktopStore(getTargetContext());store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).commit();
  getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
  launch();int version=getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionCode;
  if(phase.equals("seed")){
   check(version==15,"Seeds actual preceding 0.9.2 APK");
   ui(()->{TenThemes.TEN.get(10).apply(store);store.prefs.edit().putBoolean("taskbar_expanded",true).putBoolean("taskbar_static",true).putString("taskbar_grouping","Never").putString("eleven_taskbar_alignment","Center").putInt("desktop_columns_portrait",5).putInt("desktop_rows_portrait",9).putInt("desktop_icon_percent",80).putString("note",note).commit();store.desktop(Arrays.asList("@notes","@calendar","@recycle"));store.quickLaunch(Arrays.asList("@notes","@calendar"));store.startPins(Arrays.asList("@notes","@calendar","@photos"));JSONObject positions=new JSONObject();try{positions.put("@notes",new JSONObject().put("x",0.6).put("y",34));}catch(JSONException e){throw new RuntimeException(e);}TenDesktopItems.positions(store,"portrait",positions);home.applyTenAppearance();home.open("@notes");});waitForIdleSync();
   check(note.equals(((EditText)TenSmoke.description(home.getWindow().getDecorView(),"Notepad text")).getText().toString()),"Old APK displays seeded note");
   check(store.prefs.edit().commit(),"Seed preference writes flushed before force-stop/install");JSONObject expected=new JSONObject();for(String key:keys())expected.put(key,store.prefs.getAll().get(key));expected.put("positions",TenDesktopItems.portable(store));expected.put("iconBox",iconBox());write("eleven-upgrade-expected.json",expected.toString());write("eleven-upgrade-backup.json",DesktopBackup.snapshot(store).toString());
  }else{
   check(version==BuildConfig.VERSION_CODE,"Verifies current APK after install -r");JSONObject expected=new JSONObject(read("eleven-upgrade-expected.json"));for(String key:keys())check(String.valueOf(expected.get(key)).equals(String.valueOf(store.prefs.getAll().get(key))),"Upgrade retains "+key+" expected="+expected.get(key)+" actual="+store.prefs.getAll().get(key));check(expected.getString("positions").equals(TenDesktopItems.portable(store)),"Upgrade retains saved icon positions");write("eleven-upgrade-grid.txt","Previous tile: "+expected.getString("iconBox")+"\nCurrent tile: "+iconBox()+"\nSaved coordinates retained: "+TenDesktopItems.portable(store));ui(()->{DesktopIconGrid grid=TenSmoke.find(home.getWindow().getDecorView(),DesktopIconGrid.class);for(int i=0;i<grid.getChildCount();i++){LinearLayout tile=(LinearLayout)grid.getChildAt(i);TextView label=(TextView)tile.getChildAt(1);android.graphics.Rect visible=new android.graphics.Rect();check(label.getGlobalVisibleRect(visible)&&visible.height()==label.getHeight()&&label.getBottom()<=tile.getHeight(),"Updated grid keeps every retained desktop label fully readable");}});
   ui(()->home.open("@notes"));waitForIdleSync();check(note.equals(((EditText)TenSmoke.description(home.getWindow().getDecorView(),"Notepad text")).getText().toString()),"Upgraded APK displays retained note");
   ui(()->{DesktopWindow window=TenSmoke.find(home.getWindow().getDecorView(),DesktopWindow.class);window.closeWindow();});
   DesktopBackup.Plan original=DesktopBackup.parse(read("eleven-upgrade-backup.json"));ui(()->{store.prefs.edit().putString("note","Changed after upgrade").putBoolean("taskbar_expanded",false).commit();store.desktop(Collections.singletonList("@calendar"));});
   DesktopBackup.apply(getTargetContext(),store,original,false);check(note.equals(store.prefs.getString("note",""))&&store.prefs.getBoolean("taskbar_expanded",false),"Actual prior-version backup restores note and taskbar settings");check(expected.getString("positions").equals(TenDesktopItems.portable(store)),"Actual restore recovers full desktop layout");
   DesktopBackup.apply(getTargetContext(),store,DesktopBackup.staged(getTargetContext(),DesktopBackup.UNDO),true);check("Changed after upgrade".equals(store.prefs.getString("note",""))&&!store.prefs.getBoolean("taskbar_expanded",true),"Actual restore undo recovers intervening state");DesktopBackup.apply(getTargetContext(),store,original,false);
   ui(()->home.finish());waitForIdleSync();launch();ui(()->home.open("@notes"));waitForIdleSync();check(note.equals(((EditText)TenSmoke.description(home.getWindow().getDecorView(),"Notepad text")).getText().toString()),"Restored note survives a fresh Activity launch");for(String key:keys())check(String.valueOf(expected.get(key)).equals(String.valueOf(store.prefs.getAll().get(key))),"Fresh launch preserves restored "+key+" expected="+expected.get(key)+" actual="+store.prefs.getAll().get(key));check(expected.getString("positions").equals(TenDesktopItems.portable(store)),"Fresh launch preserves restored desktop positions");
  }
  out.putString("stream","PASS: Eleven upgrade "+phase+" "+checks+" assertions; real APK version, existing note/theme/taskbar/layout preferences, actual previous-version backup restore/undo and fresh Activity launch where applicable.\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
 String iconBox(){DesktopIconGrid grid=TenSmoke.find(home.getWindow().getDecorView(),DesktopIconGrid.class);for(int i=0;i<grid.getChildCount();i++){View v=grid.getChildAt(i);if("@notes".equals(v.getTag())){int[] p=new int[2];v.getLocationOnScreen(p);return p[0]+","+p[1]+","+v.getWidth()+","+v.getHeight();}}throw new AssertionError("Seeded desktop note exists");}
 String[] keys(){return new String[]{"wallpaper","ten_accent","ten_apps_dark","ten_light","ten_shell_style","taskbar_expanded","taskbar_static","eleven_taskbar_alignment","note","desktop_columns_portrait","desktop_rows_portrait","desktop_icon_percent","quick_launch","start_pins","taskbar_grouping"};}
 void launch(){home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();}
 void write(String name,String text)throws IOException{try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(getTargetContext().getFilesDir(),name)),StandardCharsets.UTF_8)){w.write(text);}}
 String read(String name)throws IOException{return new String(java.nio.file.Files.readAllBytes(new File(getTargetContext().getFilesDir(),name).toPath()),StandardCharsets.UTF_8);}
 void ui(Runnable action)throws Exception{FutureTask<Void> task=new FutureTask<>(action,null);home.runOnUiThread(task);task.get(25,TimeUnit.SECONDS);}void check(boolean good,String message){checks++;if(!good)throw new AssertionError(message);}
}
